// PPTist → tldraw (Razzle deck v2, docs/DESIGN.md "Studio"). Pure TS: runs in Node ≥ 23
// (type stripping) and in the browser. Records come from records.ts; the snapshot
// schema is the fork's (schema.ts, generated by dev/gen-schema.ts).
//
//   convertDeck(pptDeck)              → Deck v2 (document snapshot + derived slides)
//   convertSlide(slide, place)        → frame + child records + slide index entry
//   convertElements(els, anims, …)    → records for a group of elements (library items)
//   insertSlide(deck, pptSlide, …)    → a new frame appended to a v2 deck's document
//
// Mapping: shape → razzle-path (exact path, fill, stroke, label); text → tldraw text
// (rich text, nearest palette colour + exact colour/line height in meta.exact); line →
// tldraw line (or arrow when it has arrowheads or curves); image → image + asset;
// latex → razzle-path; groupId → group; animations → meta.build.
import { parsePath, mapPath, serializePath, pathBounds } from '../../tldraw/apps/razzle/src/shapes/svgPath.ts'
import { parseHtml, plainText, toRichText, type Para, type Run } from './html.ts'
import {
	FONT_SIZE_MULT, PALETTE, THEME_FONT_SIZE, THEME_STROKE_WIDTH, STROKE_SIZE_MULT,
	hexOf, isClear, nearestColorName, parseColor, type SizeStyle,
} from './palette.ts'
import {
	DOCUMENT_ID, PAGE_ID, indexBetween, indicesAfter, makeArrow, makeDocument, makeFrame, makeGroup,
	makeImage, makeImageAsset, makeLine, makePage, makeRazzlePath, makeText, safeIdPart, snapshotOf,
	type Arrowhead, type Json, type ShapeRecord, type StoreSnapshot, type StrokeStyle, type TLRecord,
} from './records.ts'

export const DECK_FORMAT = 'razzle-tldraw/1'
export const SLIDE_W = 1000
export const SLIDE_H = 562.5
export const GRID = { perRow: 3, gap: 120 }
export const FADED_OPACITY = 0.22
const ROW_TOLERANCE = 40

export interface BuildMeta { step: number, effect: 'appear' | 'fade' | 'disappear', until?: number }
export interface SlideElement { id: string, type: string, text: string, left: number, top: number, width: number, height: number, rotate: number, build?: BuildMeta }
export interface SlideIndex { id: string, title: string, razzle: Json, stepCount: number, elements: SlideElement[] }
export interface DeckV2 { id: string, title: string, format: typeof DECK_FORMAT, width: number, height: number, document: StoreSnapshot, slides: SlideIndex[], updatedAt?: number }

export interface ConvertOptions {
	/** Palette for nearest-colour names (default: the Razzle palette). */
	palette?: Record<string, string>
	/** Merge a faded copy under an identical full copy into one shape with `fade` (default true). */
	mergeFadePairs?: boolean
	/** Warnings about lossy conversions are pushed here. */
	warnings?: string[]
}

// ---------------------------------------------------------------- small helpers

const r3 = (v: number) => Math.round(v * 1000) / 1000
const num = (v: unknown, d = 0) => (typeof v === 'number' && Number.isFinite(v) ? v : d)

function fontKey(family: string | undefined): 'serif' | 'sans' | 'mono' {
	const f = (family || '').toLowerCase()
	if (/mono|courier|consolas|menlo|code/.test(f)) return 'mono'
	if (/inter|sans|helvetica|arial|roboto(?! mono)|system-ui|verdana/.test(f) && !/serif(?!-)/.test(f.replace('sans-serif', ''))) return 'sans'
	return 'serif'
}

/** tldraw font size style + scale for a px size. */
function sizeAndScale(px: number): { size: SizeStyle, scale: number } {
	let best: SizeStyle = 'm', bd = Infinity
	for (const s of Object.keys(FONT_SIZE_MULT) as SizeStyle[]) {
		const d = Math.abs(Math.log(px / (THEME_FONT_SIZE * FONT_SIZE_MULT[s])))
		if (d < bd) { bd = d; best = s }
	}
	return { size: best, scale: r3(px / (THEME_FONT_SIZE * FONT_SIZE_MULT[best])) }
}

function strokeOf(color: string, width: number, style: string | undefined, palette: Record<string, string>): { stroke: StrokeStyle, exact: Json } {
	const name = nearestColorName(color, palette)
	const hex = hexOf(color) ?? palette[name]
	const w = Math.max(0.25, width || 2)
	return {
		stroke: { color: name, dash: style === 'dashed' ? 'dashed' : style === 'dotted' ? 'dotted' : 'solid', size: 's', scale: r3(w / (THEME_STROKE_WIDTH * STROKE_SIZE_MULT.s)) },
		exact: { color: hex, of: name },
	}
}

/** CSS colour for a razzle-path fill/stroke: '#rrggbb', 'rgba(…)' when translucent, or 'none'. */
function cssFill(c: string | undefined): string {
	if (isClear(c)) return 'none'
	const p = parseColor(c!)
	if (!p) return c!
	return p.a < 1 ? `rgba(${p.r}, ${p.g}, ${p.b}, ${r3(p.a)})` : hexOf(c)!
}

function fadedOf(c: string): [number, number, number] | null {
	const p = parseColor(c)
	if (!p) return null
	const f = (v: number) => v * FADED_OPACITY + 255 * (1 - FADED_OPACITY)
	return [f(p.r), f(p.g), f(p.b)]
}
/** Is `under` the faded rendering of `over`? (FADED_OPACITY over white, generous tolerance) */
function looksFaded(under: string | undefined, over: string | undefined): boolean {
	if (isClear(under) && isClear(over)) return true
	if (isClear(under) || isClear(over)) return false
	const f = fadedOf(over!), u = parseColor(under!)
	if (!f || !u) return false
	return Math.max(Math.abs(u.r - f[0]), Math.abs(u.g - f[1]), Math.abs(u.b - f[2])) <= 40
}

function rotateAbout(px: number, py: number, cx: number, cy: number, rad: number): [number, number] {
	const c = Math.cos(rad), s = Math.sin(rad)
	const dx = px - cx, dy = py - cy
	return [cx + dx * c - dy * s, cy + dx * s + dy * c]
}

/** The visible text of a PPTist element (for titles and the slide index). */
export function pptElementText(el: Json): string {
	if (el?.type === 'text') return plainText(parseHtml(el.content ?? '')).replace(/\u00a0/g, ' ').trim()
	if (el?.type === 'shape' && el.text?.content) return plainText(parseHtml(el.text.content)).replace(/\u00a0/g, ' ').trim()
	if (el?.type === 'latex') return el.latex ?? ''
	if (el?.type === 'table') return (el.data ?? []).map((row: Json[]) => row.map((c) => plainText(parseHtml(c?.text ?? ''))).join(' | ')).join('\n')
	if (el?.type === 'chart') return [...(el.data?.labels ?? []), ...(el.data?.legends ?? [])].join(', ')
	return ''
}

// ---------------------------------------------------------------- builds

/** Step at which each animation plays: each `click` opens a new step; a leading
 *  non-click group plays with the slide (step 0), as the server's stepCountOf counts. */
export function animationSteps(anims: Json[]): number[] {
	let step = 0
	return anims.map((a) => (a.trigger === 'click' ? ++step : step))
}

/** The build of one element from the animations that name it (null = never visible). */
function buildFor(events: { step: number, type: string }[], maxStep: number): BuildMeta | null | undefined {
	const ev = events.filter((e) => e.type === 'in' || e.type === 'out')
	if (!ev.length) return undefined
	const vis: boolean[] = []
	let v = ev[0].type !== 'in'
	let i = 0
	for (let s = 0; s <= maxStep; s++) {
		while (i < ev.length && ev[i].step <= s) { v = ev[i].type === 'in'; i++ }
		vis.push(v)
	}
	const changes: number[] = []
	for (let s = 1; s < vis.length; s++) if (vis[s] !== vis[s - 1]) changes.push(s)
	if (!changes.length) return vis[0] ? undefined : null
	const effect = vis[0] ? 'disappear' : 'appear'
	const b: BuildMeta = { step: changes[0], effect }
	if (changes.length > 1) b.until = changes[1]
	return b
}

// ---------------------------------------------------------------- element model

interface Item {
	el: Json
	z: number
	build?: BuildMeta
	drop?: boolean
}

function sameBox(a: Json, b: Json, tol = 1): boolean {
	return Math.abs(num(a.left) - num(b.left)) <= tol && Math.abs(num(a.top) - num(b.top)) <= tol &&
		Math.abs(num(a.width) - num(b.width)) <= tol && Math.abs(num(a.height) - num(b.height)) <= tol &&
		Math.abs(num(a.rotate) - num(b.rotate)) < 0.5
}

function textColors(el: Json): string[] {
	const paras = parseHtml(el.content ?? '')
	const cs = new Set<string>()
	for (const p of paras) for (const r of p.runs) if (r.text.trim()) cs.add(hexOf(r.color ?? el.defaultColor) ?? '')
	return [...cs]
}

/** Is `under` a faded copy of `over` (same geometry and content, colours faded)? */
function isFadedCopy(under: Json, over: Json): boolean {
	if (under.type !== over.type) return false
	switch (over.type) {
		case 'text': {
			if (!sameBox(under, over)) return false
			if (pptElementText(under) !== pptElementText(over)) return false
			const uc = textColors(under), oc = textColors(over)
			return uc.length === 1 && oc.length >= 1 && oc.every((c) => looksFaded(uc[0], c) || uc[0] === '#cccccc')
		}
		case 'shape': {
			if (!sameBox(under, over)) return false
			const pathEq = under.pathFormula && over.pathFormula
				? under.pathFormula === over.pathFormula && JSON.stringify(under.keypoints) === JSON.stringify(over.keypoints)
				: serializePath(parsePath(under.path)) === serializePath(parsePath(over.path))
			if (!pathEq || !!under.flipH !== !!over.flipH || !!under.flipV !== !!over.flipV) return false
			if (!looksFaded(under.fill, over.fill)) return false
			const uo = under.outline, oo = over.outline
			if (!!uo?.width !== !!oo?.width) return false
			if (uo?.width && !looksFaded(uo.color, oo.color)) return false
			if ((under.text?.content ? pptElementText(under) : '') !== (over.text?.content ? pptElementText(over) : '')) return false
			return true
		}
		case 'line': {
			const p = (e: Json, k: 'start' | 'end') => [num(e.left) + e[k][0], num(e.top) + e[k][1]]
			const near = (a: number[], b: number[]) => Math.abs(a[0] - b[0]) <= 1 && Math.abs(a[1] - b[1]) <= 1
			const fwd = near(p(under, 'start'), p(over, 'start')) && near(p(under, 'end'), p(over, 'end'))
			const rev = near(p(under, 'start'), p(over, 'end')) && near(p(under, 'end'), p(over, 'start'))
			if (!fwd && !rev) return false
			if (!!under.curve !== !!over.curve || !!under.broken !== !!over.broken || !!under.cubic !== !!over.cubic) return false
			return looksFaded(under.color, over.color)
		}
	}
	return false
}

function prepareItems(elements: Json[], animations: Json[] | undefined, o: ConvertOptions): Item[] {
	const items: Item[] = elements.map((el, z) => ({ el, z }))
	const byId = new Map(items.map((it) => [it.el.id, it]))
	const anims = (animations ?? []).filter((a) => byId.has(a.elId))
	const steps = animationSteps(anims)
	const maxStep = steps.length ? Math.max(...steps) : 0
	const events = new Map<string, { step: number, type: string }[]>()
	anims.forEach((a, i) => {
		if (!events.has(a.elId)) events.set(a.elId, [])
		events.get(a.elId)!.push({ step: steps[i], type: a.type })
	})
	for (const it of items) {
		const b = buildFor(events.get(it.el.id) ?? [], maxStep)
		if (b === null) it.drop = true
		else if (b) it.build = b
	}
	if (o.mergeFadePairs !== false) {
		// a full copy that appears over an identical faded copy becomes one shape that fades in
		for (const over of items) {
			if (over.drop || over.build?.effect !== 'appear') continue
			for (let j = over.z - 1; j >= 0; j--) {
				const under = items[j]
				if (under.drop || under.build) continue
				if (isFadedCopy(under.el, over.el)) {
					under.drop = true
					over.build = { ...over.build, effect: 'fade' }
					break
				}
			}
		}
	}
	return items
}

// ---------------------------------------------------------------- emitting shapes

interface Emitted {
	/** Records in z-order; parentId/index are filled in by the caller. */
	shapes: ShapeRecord[]
	assets: TLRecord[]
	/** Slide-index entries for the emitted shapes (slide coordinates). */
	index: SlideElement[]
}

interface Ctx {
	prefix: string
	palette: Record<string, string>
	warnings: string[]
	used: Set<string>
}

function uid(ctx: Ctx, base: string): string {
	let id = `shape:${safeIdPart(ctx.prefix + base)}`
	let n = 1
	while (ctx.used.has(id)) id = `shape:${safeIdPart(ctx.prefix + base)}-${++n}`
	ctx.used.add(id)
	return id
}

/** A shape record not yet placed in the tree (parent/index assigned later). */
function shapeBase(id: string, x: number, y: number, rotation = 0, opacity = 1, meta: Json = {}) {
	return { id, parentId: PAGE_ID, index: 'a1', x: r3(x), y: r3(y), rotation, opacity: Math.max(0, Math.min(1, opacity)), meta }
}

function placeRotated(el: Json, x0: number, y0: number): { x: number, y: number, rotation: number } {
	const deg = num(el.rotate)
	if (!deg) return { x: x0, y: y0, rotation: 0 }
	const rad = (deg * Math.PI) / 180
	const cx = num(el.left) + num(el.width) / 2, cy = num(el.top) + num(el.height) / 2
	const [x, y] = rotateAbout(x0, y0, cx, cy, rad)
	return { x, y, rotation: rad }
}

function labelOf(t: Json | undefined, defaultFont: string) {
	if (!t?.content) return null
	const paras = parseHtml(t.content)
	if (!plainText(paras).trim()) return null
	const first = paras.flatMap((p) => p.runs).find((r) => r.text.trim()) ?? ({} as Run)
	const align = paras[0]?.align ?? 'center'
	return {
		richText: toRichText(codeMarks(nbspToSpace(paras), fontKey(first.font ?? t.defaultFontName ?? defaultFont))),
		font: fontKey(first.font ?? t.defaultFontName ?? defaultFont),
		fontSize: first.size ?? 16,
		labelColor: hexOf(first.color ?? t.defaultColor) ?? '#000000',
		align: (align === 'center' ? 'middle' : align === 'right' ? 'end' : 'start') as 'start' | 'middle' | 'end',
		verticalAlign: (t.align === 'top' ? 'start' : t.align === 'bottom' ? 'end' : 'middle') as 'start' | 'middle' | 'end',
		lineHeight: r3(lineBox(first.size ?? PM_BASE, num(t.lineHeight, 1.5)) / (first.size ?? PM_BASE)),
		padding: Array.isArray(t.inset) && t.inset.length === 4 ? t.inset.map((v: unknown) => num(v)) : [10, 10, 10, 10],
	}
}

/** PPTist's line box: the paragraph strut is 16px (ProseMirror's base size), so text smaller
 *  than 16px still gets lineHeight × 16px lines. */
const PM_BASE = 16
function lineBox(size: number, lh: number) {
	return lh * Math.max(size, PM_BASE)
}

/** Monospace runs inside non-mono text become tldraw `code` marks. */
function codeMarks(paras: Para[], base: string): Para[] {
	if (base === 'mono') return paras
	return paras.map((p) => ({ ...p, runs: p.runs.map((r) => (r.font && fontKey(r.font) === 'mono' ? { ...r, code: true } : r)) }))
}

/** Lines a paragraph takes when word-wrapped at `cols` characters (as CSS break-word does). */
function wrappedLines(text: string, cols: number): number {
	let lines = 1, col = 0
	for (const word of text.split(/(\s+)/)) {
		if (!word) continue
		if (/^\s+$/.test(word)) { col += word.length; continue }
		let w = word.length
		if (col > 0 && col + w > cols) { lines++; col = 0 }
		while (w > cols) { lines++; w -= cols }
		col += w
	}
	return lines
}

function nbspToSpace(paras: Para[]): Para[] {
	return paras.map((p) => ({ ...p, runs: p.runs.map((r) => ({ ...r, text: r.text.replace(/\u00a0/g, ' ') })) }))
}

function emitShape(el: Json, ctx: Ctx): Emitted {
	const vb: [number, number] = Array.isArray(el.viewBox) ? [num(el.viewBox[0], el.width), num(el.viewBox[1], el.height)] : [num(el.width, 1), num(el.height, 1)]
	let segs = parsePath(el.path ?? '')
	if (el.flipH) segs = mapPath(segs, -1, vb[0], 1, 0)
	if (el.flipV) segs = mapPath(segs, 1, 0, -1, vb[1])
	let fill = el.fill
	if (el.gradient?.colors?.length) fill = el.gradient.colors[0].color
	const o = el.outline
	const strokeWidth = o ? num(o.width, 0) : 0
	const mixed = el.text?.content && labelStyles(el.text) > 1
	const label = mixed ? null : labelOf(el.text, 'Libre Baskerville')
	const { x, y, rotation } = placeRotated(el, num(el.left), num(el.top))
	const id = uid(ctx, el.id)
	const rec = makeRazzlePath(shapeBase(id, x, y, rotation, num(el.opacity, 1), el.name ? { name: el.name } : {}), {
		w: num(el.width, 1), h: num(el.height, 1), path: serializePath(segs), viewW: vb[0], viewH: vb[1],
		fill: cssFill(fill),
		stroke: o && strokeWidth > 0 ? cssFill(o.color || '#d14424') : 'none',
		strokeWidth, dash: o?.style ?? 'solid',
		...(label ?? {}),
	})
	const out: Emitted = { shapes: [rec], assets: [], index: [indexEntry(id, 'razzle-path', label ? pptElementText(el) : '', el)] }
	if (mixed) {
		// a label whose paragraphs differ in size, font or colour: tldraw rich text has one
		// style per shape, so each run of paragraphs becomes a text shape over the box
		const t = el.text
		const txt = emitText({
			id: `${el.id}-label`, type: 'text', left: num(el.left), top: num(el.top), width: num(el.width), height: num(el.height), rotate: num(el.rotate),
			content: t.content, defaultFontName: t.defaultFontName, defaultColor: t.defaultColor, lineHeight: t.lineHeight, paragraphSpace: t.paragraphSpace ?? 5,
			inset: t.inset, fixedHeight: true, vAlign: t.align ?? 'middle', opacity: el.opacity,
		}, ctx)
		out.shapes.push(...txt.shapes)
		out.index.push(...txt.index)
	}
	return out
}

/** Number of distinct (size, font, colour) paragraph styles in a shape's text. */
function labelStyles(t: Json): number {
	const keys = new Set<string>()
	for (const p of parseHtml(t.content)) {
		const r = p.runs.find((x) => x.text.trim())
		if (r) keys.add(`${r.size ?? PM_BASE}|${fontKey(r.font ?? t.defaultFontName)}|${hexOf(r.color ?? t.defaultColor)}`)
	}
	return keys.size
}

function emitLatex(el: Json, ctx: Ctx): Emitted {
	const { x, y, rotation } = placeRotated(el, num(el.left), num(el.top))
	const id = uid(ctx, el.id)
	const rec = makeRazzlePath(shapeBase(id, x, y, rotation), {
		w: num(el.width, 1), h: num(el.height, 1), path: el.path ?? '', viewW: num(el.viewBox?.[0], el.width), viewH: num(el.viewBox?.[1], el.height),
		fill: 'none', stroke: hexOf(el.color) ?? '#000000', strokeWidth: num(el.strokeWidth, 2), dash: 'solid',
	})
	return { shapes: [rec], assets: [], index: [indexEntry(id, 'razzle-path', el.latex ?? '', el)] }
}

function indexEntry(id: string, type: string, text: string, el: Json, box?: { left: number, top: number, width: number, height: number }): SlideElement {
	const b = box ?? { left: num(el.left), top: num(el.top), width: num(el.width), height: num(el.height) }
	return { id, type, text, left: r3(b.left), top: r3(b.top), width: r3(b.width), height: r3(b.height), rotate: num(el.rotate) }
}

/** One text shape per run of paragraphs that share colour, size and font. */
function emitText(el: Json, ctx: Ctx): Emitted {
	const box = el
	const contentHtml: string = el.content ?? ''
	const inset: number[] = Array.isArray(el.inset) && el.inset.length === 4 ? el.inset.map((v: unknown) => num(v)) : [10, 10, 10, 10]
	const lh = num(el.lineHeight, 1.5)
	const ps = num(el.paragraphSpace, 5)
	const paras = nbspToSpace(parseHtml(contentHtml))
	const out: Emitted = { shapes: [], assets: [], index: [] }
	const left = num(box.left), top = num(box.top), width = num(box.width), height = num(box.height)

	const styleOfPara = (p: Para) => {
		const runs = p.runs.filter((r) => r.text.trim())
		const weight = new Map<string, number>()
		for (const r of runs) {
			const c = hexOf(r.color ?? el.defaultColor) ?? '#000000'
			weight.set(c, (weight.get(c) ?? 0) + r.text.length)
		}
		const dflt = hexOf(el.defaultColor) ?? '#000000'
		// mixed colours in one line (keywords in code): tldraw text has one colour; keep the base colour
		const color = weight.size > 1 && weight.has(dflt) ? dflt : [...weight.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? dflt
		if (weight.size > 1) ctx.warnings.push(`${el.id}: mixed colours in one line, using ${color}`)
		const first = runs[0] ?? p.runs[0] ?? ({} as Run)
		return { color, size: first.size ?? 16, font: fontKey(first.font ?? el.defaultFontName), align: p.align }
	}
	type Chunk = { paras: Para[], style: ReturnType<typeof styleOfPara>, y: number }
	const chunks: Chunk[] = []
	let yy = 0
	for (const p of paras) {
		const st = styleOfPara(p)
		const last = chunks[chunks.length - 1]
		const key = (s: typeof st) => `${s.color}|${s.size}|${s.font}`
		if (last && key(last.style) === key(st)) last.paras.push(p)
		else chunks.push({ paras: [p], style: st, y: yy })
		yy += lineBox(st.size, lh) + ps
	}
	const contentH = yy - (paras.length ? ps : 0)
	let dy = 0
	if (el.fixedHeight && (el.vAlign === 'middle' || el.vAlign === 'bottom')) {
		const free = height - inset[0] - inset[2] - contentH
		dy = el.vAlign === 'middle' ? free / 2 : free
	}
	const innerW = Math.max(1, width - inset[1] - inset[3])

	// background fill and outline as a rectangle under the text. PPTist grows a text box to
	// its content unless fixedHeight; mono text (code) wraps predictably, so estimate that.
	if (!isClear(el.fill) || (el.outline?.width && !isClear(el.outline.color))) {
		let h = height
		if (!el.fixedHeight) {
			let est = 0
			for (const p of paras) {
				const st = styleOfPara(p)
				const lines = st.font === 'mono' ? wrappedLines(plainText([p]), Math.max(1, Math.floor(innerW / (0.6 * st.size)))) : 1
				est += lines * lineBox(st.size, lh) + ps
			}
			h = Math.max(height, r3(inset[0] + inset[2] + est - (paras.length ? ps : 0)))
		}
		const { x, y, rotation } = placeRotated(el, left, top)
		const id = uid(ctx, `${el.id}-bg`)
		out.shapes.push(makeRazzlePath(shapeBase(id, x, y, rotation, num(el.opacity, 1)), {
			w: width, h, path: `M 0 0 L ${width} 0 L ${width} ${h} L 0 ${h} Z`, viewW: width, viewH: h,
			fill: cssFill(el.fill), stroke: el.outline?.width ? cssFill(el.outline.color) : 'none', strokeWidth: num(el.outline?.width, 0), dash: el.outline?.style ?? 'solid',
		}))
	}
	chunks.forEach((ch, i) => {
		if (!plainText(ch.paras).trim() && chunks.length > 1) return
		const { size, scale } = sizeAndScale(ch.style.size)
		const name = nearestColorName(ch.style.color, ctx.palette)
		const x0 = left + inset[3], y0 = top + inset[0] + dy + ch.y
		const { x, y, rotation } = placeRotated(el, x0, y0)
		const id = uid(ctx, chunks.length > 1 ? `${el.id}-${i + 1}` : el.id)
		const a = ch.style.align
		out.shapes.push(makeText(shapeBase(id, x, y, rotation, num(el.opacity, 1), { exact: { color: ch.style.color, of: name, lineHeight: r3(lineBox(ch.style.size, lh) / ch.style.size) }, ...(el.name ? { name: el.name } : {}) }), {
			richText: toRichText(codeMarks(ch.paras, ch.style.font)), color: name, size, font: ch.style.font,
			textAlign: a === 'center' ? 'middle' : a === 'right' ? 'end' : 'start',
			w: r3(innerW / scale), scale, autoSize: false,
		}))
		const h = ch.paras.length * lineBox(ch.style.size, lh)
		out.index.push(indexEntry(id, 'text', plainText(ch.paras).trim(), el, { left: x0, top: y0, width: innerW, height: h }))
	})
	return out
}

function lineArrowheads(el: Json): [Arrowhead, Arrowhead] {
	const m = (p: string): Arrowhead => (p === 'arrow' ? 'triangle' : p === 'dot' ? 'dot' : 'none')
	return [m(el.points?.[0] ?? ''), m(el.points?.[1] ?? '')]
}

function emitLine(el: Json, ctx: Ctx): Emitted {
	const L = num(el.left), T = num(el.top)
	const s: [number, number] = [L + num(el.start?.[0]), T + num(el.start?.[1])]
	const e: [number, number] = [L + num(el.end?.[0]), T + num(el.end?.[1])]
	const { stroke, exact } = strokeOf(el.color, num(el.width, 2), el.style, ctx.palette)
	const [hs, he] = lineArrowheads(el)
	if (el.curve || el.cubic || ((el.broken || el.broken2) && (hs !== 'none' || he !== 'none'))) {
		// curves, and elbows with arrowheads: the exact PPTist drawing (stroke path + marker shapes)
		return emitPathLine(el, ctx, s, e)
	}
	const id = uid(ctx, el.id)
	const meta = { exact, ...(el.name ? { name: el.name } : {}) }
	const base = shapeBase(id, s[0], s[1], 0, 1, meta)
	const rel = (p: [number, number]): [number, number] => [r3(p[0] - s[0]), r3(p[1] - s[1])]
	let rec: ShapeRecord
	let pts: [number, number][] = [s, e]
	if (el.broken || el.broken2) {
		const mids: [number, number][] = el.broken
			? [[L + el.broken[0], T + el.broken[1]]]
			: el.broken2Direction === 'vertical'
				? [[s[0], T + el.broken2[1]], [e[0], T + el.broken2[1]]]
				: [[L + el.broken2[0], s[1]], [L + el.broken2[0], e[1]]]
		pts = [s, ...mids, e]
		rec = makeLine(base, stroke, pts.map(rel))
	} else if (hs !== 'none' || he !== 'none') {
		rec = makeArrow(base, stroke, { start: [0, 0], end: rel(e), arrowheadStart: hs, arrowheadEnd: he })
	} else {
		rec = makeLine(base, stroke, [[0, 0], rel(e)])
	}
	const xs = pts.map((p) => p[0]), ys = pts.map((p) => p[1])
	const box = { left: Math.min(...xs), top: Math.min(...ys), width: Math.max(...xs) - Math.min(...xs), height: Math.max(...ys) - Math.min(...ys) }
	return { shapes: [rec], assets: [], index: [{ ...indexEntry(id, rec.type, el.name ?? '', el, box), rotate: 0 }] }
}

/** PPTist line dash arrays (BaseLineElement), by width. */
function lineDash(style: string | undefined, w: number): string {
	if (style === 'dashed') return w <= 8 ? `${w * 5} ${w * 2.5}` : `${w * 5} ${w * 1.5}`
	if (style === 'dotted') return w <= 8 ? `${w * 1.8} ${w * 1.6}` : `${w * 1.5} ${w * 1.2}`
	return 'solid'
}

/** A line drawn exactly as PPTist does: the stroke as a razzle-path (retracted under its
 *  markers) and each arrow/dot marker as a filled razzle-path, grouped. */
function emitPathLine(el: Json, ctx: Ctx, s: [number, number], e: [number, number]): Emitted {
	const L = num(el.left), T = num(el.top)
	const P = (p: number[]): [number, number] => [L + p[0], T + p[1]]
	const w = Math.max(0.25, num(el.width, 2))
	const color = hexOf(el.color) ?? '#000000'
	const turns: [number, number][] = el.cubic ? [P(el.cubic[0]), P(el.cubic[1])] : el.curve ? [P(el.curve)] : el.broken ? [P(el.broken)]
		: el.broken2 ? (el.broken2Direction === 'vertical' ? [[s[0], T + el.broken2[1]], [e[0], T + el.broken2[1]]] : [[L + el.broken2[0], s[1]], [L + el.broken2[0], e[1]]]) : []
	const ms = Math.max(w, 2)
	const unit = (a: number[], b: number[]) => { const d = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1; return [(b[0] - a[0]) / d, (b[1] - a[1]) / d] }
	const along = (p: number[], q: number[], off: number): [number, number] => { const d = Math.hypot(q[0] - p[0], q[1] - p[1]) || 1; const o = Math.min(off, d / 2); return [p[0] + (q[0] - p[0]) * o / d, p[1] + (q[1] - p[1]) * o / d] }
	const [ps, pe] = [el.points?.[0] ?? '', el.points?.[1] ?? '']
	const off = (k: string) => (k === 'arrow' ? ms : k === 'dot' ? ms / 2 : 0)
	const s2 = off(ps) ? along(s, turns[0] ?? e, off(ps)) : s
	const e2 = off(pe) ? along(e, turns[turns.length - 1] ?? s, off(pe)) : e
	const f = (p: number[]) => `${r3(p[0])} ${r3(p[1])}`
	let d: string
	if (el.cubic) d = `M ${f(s2)} C ${f(turns[0])} ${f(turns[1])} ${f(e2)}`
	else if (el.curve) d = `M ${f(s2)} Q ${f(turns[0])} ${f(e2)}`
	else d = `M ${f(s2)} ${[...turns, e2].map((p) => `L ${f(p)}`).join(' ')}`
	const out: Emitted = { shapes: [], assets: [], index: [] }
	const pathShape = (key: string, d: string, fill: string, stroke: string, sw: number, dash: string) => {
		const segs = parsePath(d)
		const b = pathBounds(segs)
		const bw = Math.max(b.w, 1), bh = Math.max(b.h, 1)
		const ox = b.x - (bw - b.w) / 2, oy = b.y - (bh - b.h) / 2
		const id = uid(ctx, key)
		out.shapes.push(makeRazzlePath(shapeBase(id, ox, oy, 0, 1, el.name ? { name: el.name } : {}), {
			w: r3(bw), h: r3(bh), viewW: r3(bw), viewH: r3(bh), path: serializePath(mapPath(segs, 1, -ox, 1, -oy)),
			fill, stroke, strokeWidth: sw, dash,
		}))
		return { id, b }
	}
	const body = pathShape(el.id, d, 'none', color, w, lineDash(el.style, w))
	out.index.push({ ...indexEntry(body.id, 'razzle-path', el.name ?? '', el, { left: body.b.x, top: body.b.y, width: body.b.w, height: body.b.h }), rotate: 0 })
	const marker = (kind: string, at: [number, number], from: number[], key: string) => {
		const u = unit(from, at) // pointing out of the line at this end
		const n = [-u[1], u[0]]
		if (kind === 'arrow') {
			const base = [at[0] - u[0] * 3 * ms, at[1] - u[1] * 3 * ms]
			const a = [base[0] + n[0] * 1.5 * ms, base[1] + n[1] * 1.5 * ms], b2 = [base[0] - n[0] * 1.5 * ms, base[1] - n[1] * 1.5 * ms]
			pathShape(key, `M ${f(at)} L ${f(a)} L ${f(b2)} Z`, color, 'none', 0, 'solid')
		} else if (kind === 'dot') {
			const r = 1.5 * ms, c = [at[0] - u[0] * r, at[1] - u[1] * r]
			pathShape(key, `M ${f([c[0] - r, c[1]])} A ${r3(r)} ${r3(r)} 0 1 0 ${f([c[0] + r, c[1]])} A ${r3(r)} ${r3(r)} 0 1 0 ${f([c[0] - r, c[1]])} Z`, color, 'none', 0, 'solid')
		}
	}
	if (pe) marker(pe, e, turns[turns.length - 1] ?? s, `${el.id}-end`)
	if (ps) marker(ps, s, turns[0] ?? e, `${el.id}-start`)
	return out
}

function emitImage(el: Json, ctx: Ctx): Emitted {
	const id = uid(ctx, el.id)
	const aid = `asset:${safeIdPart(ctx.prefix + el.id)}`
	const { x, y, rotation } = placeRotated(el, num(el.left), num(el.top))
	const w = num(el.width, 1), h = num(el.height, 1)
	const asset = makeImageAsset(aid, String(el.src ?? ''), w, h, el.name ?? 'image')
	const img = makeImage(shapeBase(id, x, y, rotation, num(el.opacity, 1)), { w, h, assetId: aid, flipX: el.flipH, flipY: el.flipV })
	const range = el.clip?.range
	if (Array.isArray(range) && range.length === 2) {
		const [[x1, y1], [x2, y2]] = range
		if (x1 !== 0 || y1 !== 0 || x2 !== 100 || y2 !== 100) img.props.crop = { topLeft: { x: x1 / 100, y: y1 / 100 }, bottomRight: { x: x2 / 100, y: y2 / 100 } }
	}
	return { shapes: [img], assets: [asset], index: [indexEntry(id, 'image', el.name ?? '', el)] }
}

/** Tables, charts, video and audio: a labelled placeholder box (lossy). */
function emitPlaceholder(el: Json, ctx: Ctx): Emitted {
	ctx.warnings.push(`${el.id}: ${el.type} elements are not supported; drawn as a placeholder box`)
	const text = pptElementText(el) || el.type
	const w = num(el.width, 100), h = num(el.height, 60)
	const { x, y, rotation } = placeRotated(el, num(el.left), num(el.top))
	const id = uid(ctx, el.id)
	const rec = makeRazzlePath(shapeBase(id, x, y, rotation), {
		w, h, path: `M 0 0 L ${w} 0 L ${w} ${h} L 0 ${h} Z`, viewW: w, viewH: h,
		fill: '#f3f3f3', stroke: '#595959', strokeWidth: 1, dash: 'dashed',
		richText: toRichText(text.split("\n").map((t: string) => ({ align: 'center', runs: [{ text: t }] }))),
		font: 'serif', fontSize: 14, labelColor: '#595959',
	})
	return { shapes: [rec], assets: [], index: [indexEntry(id, 'razzle-path', text, el)] }
}

function emitElement(el: Json, ctx: Ctx): Emitted {
	switch (el.type) {
		case 'shape': return emitShape(el, ctx)
		case 'text': return emitText(el, ctx)
		case 'line': return emitLine(el, ctx)
		case 'image': return emitImage(el, ctx)
		case 'latex': return emitLatex(el, ctx)
		default: return emitPlaceholder(el, ctx)
	}
}

// ---------------------------------------------------------------- tree assembly

interface Node {
	shape: ShapeRecord
	children?: Node[]
	build?: BuildMeta
}

/** Group nodes around (x, y) = min of their children's positions; children made relative. */
function groupNode(id: string, children: Node[], build?: BuildMeta, meta: Json = {}): Node {
	const x = Math.min(...children.map((c) => c.shape.x)), y = Math.min(...children.map((c) => c.shape.y))
	for (const c of children) { c.shape.x = r3(c.shape.x - x); c.shape.y = r3(c.shape.y - y) }
	return { shape: makeGroup({ ...shapeBase(id, x, y), meta }), children, build }
}

function sameBuild(a?: BuildMeta, b?: BuildMeta) {
	return JSON.stringify(a ?? null) === JSON.stringify(b ?? null)
}

/** Elements → a forest of nodes (PPTist groups become tldraw groups). Positions are slide-relative. */
function buildForest(elements: Json[], animations: Json[] | undefined, ctx: Ctx, o: ConvertOptions, index: SlideElement[], assets: TLRecord[]): Node[] {
	const items = prepareItems(elements, animations, o)
	const top: (Node | { group: string, nodes: Node[], builds: (BuildMeta | undefined)[] })[] = []
	const groups = new Map<string, { group: string, nodes: Node[], builds: (BuildMeta | undefined)[] }>()
	for (const it of items) {
		if (it.drop) continue
		const em = emitElement(it.el, ctx)
		assets.push(...em.assets)
		for (const e of em.index) index.push(it.build ? { ...e, build: it.build } : e)
		if (!em.shapes.length) continue
		let node: Node
		if (em.shapes.length === 1) node = { shape: em.shapes[0], build: it.build }
		else node = groupNode(uid(ctx, `${it.el.id}-group`), em.shapes.map((s) => ({ shape: s })), it.build)
		const gid = it.el.groupId
		if (gid) {
			let g = groups.get(gid)
			if (!g) { g = { group: gid, nodes: [], builds: [] }; groups.set(gid, g); top.push(g) }
			g.nodes.push(node)
			g.builds.push(it.build)
		} else top.push(node)
	}
	const out: Node[] = []
	for (const t of top) {
		if ('shape' in t) { out.push(t); continue }
		if (t.nodes.length === 1) { out.push(t.nodes[0]); continue }
		// a build shared by every member moves to the group
		const shared = t.builds.every((b) => sameBuild(b, t.builds[0])) ? t.builds[0] : undefined
		if (shared) for (const n of t.nodes) n.build = undefined
		out.push(groupNode(uid(ctx, `g-${t.group}`), t.nodes, shared))
	}
	return out
}

/** Flatten nodes under a parent: parentId, index, and meta.build assigned. */
function flatten(nodes: Node[], parentId: string, out: ShapeRecord[]) {
	const keys = indicesAfter(null, nodes.length)
	nodes.forEach((n, i) => {
		n.shape.parentId = parentId
		n.shape.index = keys[i]
		if (n.build) n.shape.meta = { ...n.shape.meta, build: n.build }
		out.push(n.shape)
		if (n.children) flatten(n.children, n.shape.id, out)
	})
}

// ---------------------------------------------------------------- public API

export interface ConvertedElements {
	/** Shape records, parented to `parentId` (top level) or to their groups, in z-order. */
	shapes: ShapeRecord[]
	assets: TLRecord[]
	index: SlideElement[]
	warnings: string[]
}

/** Convert loose PPTist elements (a library item, a pasted group) under `parentId`. */
export function convertElements(elements: Json[], animations: Json[] | undefined, parentId: string, opts: ConvertOptions & { prefix?: string } = {}): ConvertedElements {
	const ctx: Ctx = { prefix: opts.prefix ?? '', palette: opts.palette ?? PALETTE, warnings: opts.warnings ?? [], used: new Set() }
	const index: SlideElement[] = []
	const assets: TLRecord[] = []
	const forest = buildForest(elements, animations, ctx, opts, index, assets)
	const shapes: ShapeRecord[] = []
	flatten(forest, parentId, shapes)
	// the index names leaf shapes only; give each the build that governs it (own or group's)
	const byId = new Map(shapes.map((s) => [s.id, s]))
	for (const e of index) {
		let s = byId.get(e.id)
		let b: BuildMeta | undefined
		while (s && !b) { b = s.meta?.build; s = byId.get(s.parentId) }
		if (b) e.build = b
		else delete e.build
	}
	return { shapes, assets, index: index.filter((e) => byId.has(e.id)), warnings: ctx.warnings }
}

/** The slide title: the title text box, else the first text, else a fallback. */
export function slideTitle(slide: Json, fallback = 'Slide'): string {
	const els: Json[] = slide.elements ?? []
	const t = els.find((e) => e.type === 'text' && (e.textType === 'title' || e.name === 'title')) ?? els.find((e) => e.type === 'text')
	const s = t ? pptElementText(t).split('\n').map((l) => l.trim()).filter(Boolean).join(' ') : ''
	return s || fallback
}

export interface ConvertedSlide {
	frame: ShapeRecord
	records: TLRecord[]
	slide: SlideIndex
	warnings: string[]
}

/** One PPTist slide → a frame (at x, y on the page) with its shapes. */
export function convertSlide(slide: Json, place: { x: number, y: number, index: string, frameId?: string, width?: number, height?: number, title?: string }, opts: ConvertOptions = {}): ConvertedSlide {
	const W = place.width ?? SLIDE_W, H = place.height ?? SLIDE_H
	const frameId = place.frameId ?? `shape:${safeIdPart(slide.id)}`
	const razzle: Json = { ...(slide.razzle ?? {}) }
	if (slide.remark && String(slide.remark).trim()) razzle.notes = slide.remark
	const title = place.title ?? slideTitle(slide)
	const frame = makeFrame({ id: frameId, parentId: PAGE_ID, index: place.index, x: place.x, y: place.y, w: W, h: H, name: title, meta: { razzle } })
	const els: Json[] = [...(slide.elements ?? [])]
	// a non-white background becomes a locked rectangle (or image) at the bottom
	const bg = slide.background
	if (bg?.type === 'solid' && bg.color && !isClear(bg.color) && hexOf(bg.color) !== '#ffffff') {
		els.unshift({ id: '__background', type: 'shape', left: 0, top: 0, width: W, height: H, rotate: 0, viewBox: [W, H], path: `M 0 0 L ${W} 0 L ${W} ${H} L 0 ${H} Z`, fill: bg.color, fixedRatio: false, name: 'background' })
	} else if (bg?.type === 'image' && bg.image?.src) {
		els.unshift({ id: '__background', type: 'image', left: 0, top: 0, width: W, height: H, rotate: 0, src: bg.image.src, fixedRatio: false, name: 'background' })
	}
	const conv = convertElements(els, slide.animations, frameId, { ...opts, prefix: `${safeIdPart(slide.id)}-` })
	for (const s of conv.shapes) if (s.id.endsWith('__background')) s.isLocked = true
	let stepCount = 1
	for (const s of conv.shapes) {
		const b = s.meta?.build as BuildMeta | undefined
		if (b) stepCount = Math.max(stepCount, b.step + 1, (b.until ?? 0) + 1)
	}
	return {
		frame,
		records: [frame, ...conv.shapes, ...conv.assets],
		slide: { id: frameId, title, razzle, stepCount, elements: conv.index },
		warnings: conv.warnings,
	}
}

/** Grid position of the i-th slide of a row layout. */
export function gridPos(col: number, row: number, W = SLIDE_W, H = SLIDE_H) {
	return { x: col * (W + GRID.gap), y: row * (H + GRID.gap) }
}

/** PPTist deck → Deck v2. Visible slides fill rows of three; hidden slides get their own final row(s). */
export function convertDeck(ppt: Json, opts: ConvertOptions = {}): DeckV2 & { warnings: string[] } {
	const W = num(ppt.width, SLIDE_W), H = num(ppt.height, SLIDE_H)
	const slides: Json[] = ppt.slides ?? []
	const visible = slides.filter((s) => !s.razzle?.hidden), hidden = slides.filter((s) => s.razzle?.hidden)
	const order = [...visible, ...hidden]
	const keys = indicesAfter(null, order.length)
	const visRows = Math.ceil(visible.length / GRID.perRow)
	const records: TLRecord[] = [makeDocument(ppt.title ?? ''), makePage()]
	const index: SlideIndex[] = []
	const warnings: string[] = opts.warnings ?? []
	order.forEach((s, i) => {
		const k = i < visible.length ? i : i - visible.length
		const row = i < visible.length ? Math.floor(k / GRID.perRow) : visRows + Math.floor(k / GRID.perRow)
		const { x, y } = gridPos(k % GRID.perRow, row, W, H)
		const c = convertSlide(s, { x, y, index: keys[i], width: W, height: H }, { ...opts, warnings })
		records.push(...c.records)
		index.push(c.slide)
	})
	return {
		id: ppt.id, title: ppt.title ?? ppt.id, format: DECK_FORMAT, width: W, height: H,
		document: snapshotOf(records), slides: index, updatedAt: ppt.updatedAt ?? Date.now(), warnings,
	}
}

// ---------------------------------------------------------------- editing a v2 deck in place

const isRootFrame = (r: TLRecord) => r.typeName === 'shape' && r.type === 'frame' && String(r.parentId).startsWith('page:')

/** The root frames of the first page, in reading order (as the studio's getSlides). */
export function framesInOrder(doc: StoreSnapshot): ShapeRecord[] {
	const pages = Object.values(doc.store).filter((r) => r.typeName === 'page').sort((a, b) => (a.index < b.index ? -1 : 1))
	const page = pages[0]?.id ?? PAGE_ID
	const frames = Object.values(doc.store).filter((r) => isRootFrame(r) && r.parentId === page) as ShapeRecord[]
	return frames.sort((a, b) => (Math.abs(a.y - b.y) > ROW_TOLERANCE ? a.y - b.y : a.x - b.x))
}

/** Append a PPTist slide to a v2 deck as a new frame in the backstage row (generated
 *  slides, below every other slide; reading order puts it last). Mutates and returns the deck; `slides` is refreshed. */
export function insertSlide(deck: DeckV2, ppt: Json, opts: ConvertOptions & { razzle?: Json } = {}): { deck: DeckV2, slideIndex: number, frameId: string, warnings: string[] } {
	const doc = deck.document
	const W = num(deck.width, SLIDE_W), H = num(deck.height, SLIDE_H)
	const frames = framesInOrder(doc)
	const backstage = frames.filter((f) => f.meta?.razzle?.generated)
	const others = frames.filter((f) => !f.meta?.razzle?.generated)
	let x = 0, y: number
	if (backstage.length) {
		const last = backstage.reduce((a, b) => (b.x > a.x ? b : a))
		y = last.y
		x = last.x + num(last.props?.w, W) + GRID.gap
	} else {
		const bottom = others.length ? Math.max(...others.map((f) => f.y + num(f.props?.h, H))) : -GRID.gap
		y = bottom + GRID.gap * 2
	}
	return placeSlide(deck, ppt, x, y, opts)
}

/** Add a regular slide after the last one in reading order, in the next grid cell. Trailing
 *  hidden slides (backups, generated ones) form the backstage row; it moves down when the
 *  grid grows into it, so they stay last. */
export function appendSlide(deck: DeckV2, ppt: Json, opts: ConvertOptions & { razzle?: Json } = {}): { deck: DeckV2, slideIndex: number, frameId: string, warnings: string[] } {
	const doc = deck.document
	const W = num(deck.width, SLIDE_W), H = num(deck.height, SLIDE_H)
	const frames = framesInOrder(doc)
	let n = frames.length
	while (n > 0 && frames[n - 1].meta?.razzle?.hidden) n--
	const regular = frames.slice(0, n), backstage = frames.slice(n)
	let x = 0, y = 0
	if (regular.length) {
		const last = regular[regular.length - 1]
		const col = Math.round(last.x / (W + GRID.gap))
		if (col < GRID.perRow - 1) { x = last.x + W + GRID.gap; y = last.y }
		else y = last.y + H + GRID.gap
	}
	const top = backstage.length ? Math.min(...backstage.map((f) => f.y)) : Infinity
	const need = y + H + GRID.gap * 2
	if (top < need) for (const f of backstage) (doc.store[f.id] as Json).y += need - top
	return placeSlide(deck, ppt, x, y, opts)
}

function placeSlide(deck: DeckV2, ppt: Json, x: number, y: number, opts: ConvertOptions & { razzle?: Json }): { deck: DeckV2, slideIndex: number, frameId: string, warnings: string[] } {
	const doc = deck.document
	const W = num(deck.width, SLIDE_W), H = num(deck.height, SLIDE_H)
	const pageId = Object.values(doc.store).find((r) => r.typeName === 'page')?.id ?? PAGE_ID
	const siblings = Object.values(doc.store).filter((r) => r.typeName === 'shape' && r.parentId === pageId).map((r) => r.index as string).sort()
	const index = indexBetween(siblings.length ? siblings[siblings.length - 1] : null, null)
	let frameId = `shape:${safeIdPart(ppt.id)}`
	for (let n = 2; doc.store[frameId]; n++) frameId = `shape:${safeIdPart(ppt.id)}-${n}`
	const slide = { ...ppt, razzle: { ...(ppt.razzle ?? {}), ...(opts.razzle ?? {}) } }
	const c = convertSlide(slide, { x, y, index, frameId, width: W, height: H }, opts)
	c.frame.parentId = pageId
	for (const r of c.records) {
		if (doc.store[r.id]) throw new Error(`record id collision: ${r.id}`)
		doc.store[r.id] = r
	}
	deck.slides = refreshSlides(deck, [c.slide])
	return { deck, slideIndex: deck.slides.findIndex((s) => s.id === frameId), frameId, warnings: c.warnings }
}

/** Re-derive `slides` order and razzle meta from the document's frames, keeping each
 *  slide's elements/stepCount from the existing index (or from `extra`). */
export function refreshSlides(deck: DeckV2, extra: SlideIndex[] = []): SlideIndex[] {
	const known = new Map([...(deck.slides ?? []), ...extra].map((s) => [s.id, s]))
	return framesInOrder(deck.document).map((f) => {
		const s = known.get(f.id)
		return {
			id: f.id,
			title: f.props?.name ?? s?.title ?? '',
			razzle: f.meta?.razzle ?? {},
			stepCount: s?.stepCount ?? 1,
			elements: s?.elements ?? [],
		}
	})
}

/** Set fields of a frame's meta.razzle (e.g. script, notes) in the document. */
export function updateSlideMeta(deck: DeckV2, frameId: string, patch: Json): boolean {
	const f = deck.document.store[frameId]
	if (!f || f.typeName !== 'shape' || f.type !== 'frame') return false
	f.meta = { ...(f.meta ?? {}), razzle: { ...(f.meta?.razzle ?? {}), ...patch } }
	return true
}

export function isDeckV2(d: unknown): d is DeckV2 {
	return !!d && typeof d === 'object' && (d as Json).format === DECK_FORMAT && !!(d as Json).document?.store
}

export { DOCUMENT_ID, PAGE_ID }
export const _internal = { sizeAndScale, fontKey, buildFor, looksFaded, pathBounds }
